#define _XOPEN_SOURCE 700

#include <stdarg.h>
#include <stdlib.h>
#include <string.h>

#include "msg.h"
#include "util.h"

static const struct catalog_lang *current;

static const struct catalog_lang *find_lang(const char *code, size_t len)
{
	const struct catalog_lang *l;

	for (l = catalog_langs; l->code != NULL; l++)
		if (strlen(l->code) == len && strncmp(l->code, code, len) == 0)
			return l;
	return NULL;
}

/* The first non-empty of LC_ALL, LC_MESSAGES and LANG wins, as in setlocale. */
void msg_init(void)
{
	static const char *const vars[] = { "LC_ALL", "LC_MESSAGES", "LANG" };
	const char *value = NULL;
	size_t i, len;

	for (i = 0; i < sizeof vars / sizeof vars[0]; i++) {
		value = getenv(vars[i]);
		if (value != NULL && value[0] != '\0')
			break;
		value = NULL;
	}
	current = NULL;
	if (value != NULL) {
		len = strcspn(value, "_.@");
		current = find_lang(value, len);
	}
	if (current == NULL)
		current = find_lang("en", 2);
}

static const char *lookup(const struct catalog_lang *l, const char *key)
{
	const struct catalog_entry *e;

	if (l == NULL)
		return NULL;
	for (e = l->entries; e->key != NULL; e++)
		if (strcmp(e->key, key) == 0)
			return e->text;
	return NULL;
}

/* A missing translation falls back to English, then to the key itself. */
const char *msg(const char *key)
{
	const char *text;

	if (current == NULL)
		msg_init();
	text = lookup(current, key);
	if (text == NULL)
		text = lookup(find_lang("en", 2), key);
	return text != NULL ? text : key;
}

/*
 * A help section, *len bytes long: the text before the first "@ name"
 * line for name NULL, otherwise the lines after "@ name" up to the next
 * "@ " line. A name without a section gets the general help.
 */
const char *msg_help(const char *name, size_t *len)
{
	const char *text, *p, *line, *end;
	size_t n;

	if (current == NULL)
		msg_init();
	text = current != NULL ? current->help : "";
	p = text;
	if (name != NULL) {
		n = strlen(name);
		for (line = text; *line != '\0'; line = end) {
			end = strchr(line, '\n');
			end = end != NULL ? end + 1 : line + strlen(line);
			if (line[0] == '@' && line[1] == ' ' &&
			    strncmp(line + 2, name, n) == 0 &&
			    (line[2 + n] == '\n' || line[2 + n] == '\0')) {
				p = end;
				break;
			}
		}
	}
	for (line = p; *line != '\0'; line = end) {
		if (line[0] == '@' && line[1] == ' ')
			break;
		end = strchr(line, '\n');
		end = end != NULL ? end + 1 : line + strlen(line);
	}
	*len = (size_t)(line - p);
	return p;
}

void msg_print(FILE *fp, const char *key, ...)
{
	va_list ap;

	va_start(ap, key);
	vfprintf(fp, msg(key), ap);
	va_end(ap);
	fputc('\n', fp);
}

void msg_error(const char *key, ...)
{
	va_list ap;

	fputs("csm: ", stderr);
	va_start(ap, key);
	vfprintf(stderr, msg(key), ap);
	va_end(ap);
	fputc('\n', stderr);
}

/* A catalogue text with its arguments filled in, in a new string. */
char *msg_text(const char *key, ...)
{
	va_list ap;
	char *out;
	int n;

	va_start(ap, key);
	n = vsnprintf(NULL, 0, msg(key), ap);
	va_end(ap);
	out = xmalloc(n > 0 ? (size_t)n + 1 : 1);
	out[0] = '\0';
	if (n > 0) {
		va_start(ap, key);
		vsnprintf(out, (size_t)n + 1, msg(key), ap);
		va_end(ap);
	}
	return out;
}
